// Rebuilds films/kit/pulse-ring.js from ring.src.js, the vendored three.js 0.184.0 and pulse-marks.js.
//
//   node films/kit/vendor/build.mjs
//
// The output is a classic (non-module) script, so film pages keep working from file:// and in
// headless renders, where ES modules are blocked. It is committed; rebuild only when a source here
// changes. Uses the rolldown that site/node_modules already has (cd site && npm ci).
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(path.join(here, '../../../site/package.json'));
const { build } = await import(pathToFileURL(require.resolve('rolldown')).href);

await build({
  input: path.join(here, 'ring.src.js'),
  output: {
    file: path.join(here, '../pulse-ring.js'),
    format: 'iife',
    minify: true,
    postBanner: '/* Pulse ring for the film kit. Generated by films/kit/vendor/build.mjs from ring.src.js; do not edit.\n' +
      ' * three.js 0.184.0 (c) 2010-2026 three.js authors, MIT (vendor/three/LICENSE). Pulse mark geometry: vendor/pulse-marks.js. */',
  },
});
console.log('wrote films/kit/pulse-ring.js');
